/**
 * Rule: aria/disabled-link-surrogate
 * Satisfies: wcag22:4.1.2, wcag21:4.1.2
 * Spec: https://www.w3.org/TR/WCAG22/#name-role-value
 *
 * > For all user interface components (including but not limited to:
 * > form elements, links and components generated by scripts), the
 * > name and role can be programmatically determined; states,
 * > properties, and values that can be set by the user can be
 * > programmatically set; and notification of changes to these items
 * > is available to user agents, including assistive technologies.
 *
 * Source: https://www.w3.org/TR/WCAG22/#name-role-value
 *
 * Flags non-interactive elements (`<span>`, `<div>`, `<i>`, `<b>`,
 * `<em>`) used as visual surrogates for a disabled link when no
 * programmatic or textual disabled-state signal reaches the
 * accessibility tree. The motivating pattern is pagination, where the
 * active page and sibling pages are `<a>` elements but the disabled
 * "previous" (or "next" on the last page) is rendered as:
 *
 *   <li class="page-item"><span class="previous">‹ Previous</span></li>
 *
 * Sighted users see a greyed-out control; screen readers hear the
 * inner glyph/text as static prose, so the disabled-state signal —
 * and often the semantic role of "link" — is silently lost. WCAG
 * 4.1.2 requires that states can be programmatically determined.
 *
 * Detection:
 *   1. The element is one of the non-interactive "styled as a control"
 *      tags: `span`, `div`, `i`, `b`, `em`.
 *   2. Its `class` attribute contains a disabled-state token
 *      (whole-word, case-insensitive):
 *        - `disabled` / `is-disabled` — always signal a disabled control.
 *        - `previous` / `prev` / `next` / `first` / `last` — only
 *          count when a sibling link is present (pagination shape).
 *   3. At least one sibling `<a>` exists in the same parent — this
 *      is the "surrogate for a live control" disambiguator. Avoids
 *      firing on arbitrary `<span class="disabled">` far from a link.
 *
 * Passes (none of these fire a violation):
 *   - `aria-disabled="true"` is present.
 *   - `role="link"` + `aria-disabled="true"`.
 *   - Visible text contains a disabled-state word the screen reader
 *     will announce: "disabled", "unavailable", "not available".
 *
 * Out of scope:
 *   - `<a class="disabled">` (the element IS a live anchor) — a
 *     different concern; a real anchor needs `aria-disabled` plus
 *     `tabindex="-1"` to convey disabled state, and the bare glyph
 *     pattern isn't the same failure shape.
 *   - Arbitrary `<span class="disabled">` with no sibling link —
 *     likely a form-status indicator or a visual label, not a
 *     link-surrogate. Those are covered by broader 1.3.3 / 1.4.1
 *     checks and are too noisy to flag on className alone.
 */

import { defineRule } from "../../api/plugin.ts";
import {
  getHtmlAttribute,
  getJsxAttributeString,
  htmlTextContent,
  jsxTextContent,
  walkHtmlElements,
  walkJsxElements,
} from "../../engine/ast-helpers.ts";
import type {
  HtmlDocument,
  HtmlElement,
  HtmlNode,
  JsxElement,
  JsxNode,
  TsxModule,
} from "../../types/ast.ts";

/** Non-interactive tags that may stand in for a control through CSS only. */
const SURROGATE_TAGS: ReadonlySet<string> = new Set(["span", "div", "i", "b", "em"]);

/**
 * Class tokens that unambiguously signal a disabled control — fire
 * whenever any sibling link is present.
 */
const STRONG_DISABLED_TOKENS: ReadonlySet<string> = new Set(["disabled", "is-disabled"]);

/**
 * Pagination directional tokens — "previous"/"next"/"first"/"last"/"prev".
 * These only mean "disabled control" when there are sibling `<a>`s in
 * the same parent (otherwise the class is decorative). A `<span
 * class="previous">` nested in a pagination widget is the surrogate
 * shape; a `<span class="previous">` in prose isn't.
 */
const DIRECTIONAL_TOKENS: ReadonlySet<string> = new Set([
  "previous",
  "prev",
  "next",
  "first",
  "last",
]);

/**
 * Words a screen reader will announce that make the disabled state
 * part of the accessible name — case-insensitive substring match on
 * the element's inner text.
 */
const DISABLED_TEXT_WORDS: readonly string[] = ["disabled", "unavailable", "not available"];

export const rule = defineRule({
  id: "aria/disabled-link-surrogate",
  satisfies: ["wcag22:4.1.2", "wcag21:4.1.2"],
  severity: "warning",
  scope: "document",
  fixClass: "verify-in-source",
  appliesTo: {
    fileExtensions: [".html", ".htm", ".tsx", ".jsx"],
  },
  docs: {
    description:
      "Non-interactive elements (span, div, i, b, em) used as disabled-link surrogates (typically pagination's Previous/Next when there's no target) must expose the disabled state via aria-disabled, role=link + aria-disabled, or a disabled-state word in visible text — otherwise screen readers read the element as static prose and the disabled signal is lost.",
    rationale:
      'Pagination widgets and similar "row of links" components often render the unavailable control as a styled `<span>` (e.g. `<span class="previous">‹</span>` on the first page, where there is no prior page to link to). CSS greys it out for sighted users, but the surrounding `<a>` siblings are exposed as links in the accessibility tree while the surrogate is exposed as plain text — the disabled-state signal reaches sight but not the accessibility tree. WCAG 4.1.2 requires that component states be programmatically determinable. Fix by adding `aria-disabled="true"` (plus `role="link"` if the surrogate is standing in for a link), or by including a disabled-state word in the visible text so the accessible name carries the signal.',
    goodExample: `<ul class="pagination">
  <li><span class="previous" aria-disabled="true" role="link">&lsaquo; Previous</span></li>
  <li><a class="page" href="/p/2">2</a></li>
  <li><a class="page" href="/p/3">3</a></li>
</ul>`,
    badExample: `<ul class="pagination">
  <li><span class="previous">&lsaquo; Previous</span></li>
  <li><a class="page" href="/p/2">2</a></li>
  <li><a class="page" href="/p/3">3</a></li>
</ul>`,
    normativeQuote:
      "For all user interface components (including but not limited to: form elements, links and components generated by scripts), the name and role can be programmatically determined; states, properties, and values that can be set by the user can be programmatically set; and notification of changes to these items is available to user agents, including assistive technologies.",
    references: [
      "https://www.w3.org/TR/WCAG22/#name-role-value",
      "https://www.w3.org/WAI/ARIA/apg/patterns/pagination/",
      "https://www.w3.org/TR/wai-aria-1.2/#aria-disabled",
    ],
  },
  afterFile(ctx) {
    if (ctx.language === "html") {
      checkHtml(ctx.ast as HtmlDocument, (v) => ctx.emit(v));
    } else if (
      ctx.language === "tsx" ||
      ctx.language === "jsx" ||
      ctx.language === "ts" ||
      ctx.language === "js"
    ) {
      checkJsx(ctx.ast as TsxModule, (v) => ctx.emit(v));
    }
  },
});

type Emit = (v: {
  severity: "warning";
  location: { filePath: string; line: number; column: number };
  message: string;
  suggestion: string;
}) => void;

interface SurrogateHit {
  readonly kind: "strong" | "directional";
  /** The raw class token the author wrote (original casing preserved for echo). */
  readonly token: string;
}

// ---------------------------------------------------------------------------
// HTML
// ---------------------------------------------------------------------------

function checkHtml(doc: HtmlDocument, emit: Emit): void {
  const parentOf = buildHtmlParentMap(doc);
  for (const el of walkHtmlElements(doc)) {
    const tag = el.tagName.toLowerCase();
    if (!SURROGATE_TAGS.has(tag)) continue;
    const classValue = getHtmlAttribute(el, "class");
    if (classValue === null) continue;
    const hit = firstSurrogateHit(classValue);
    if (hit === null) continue;
    if (!htmlNearSiblingAnchor(el, parentOf)) continue;
    // Pass conditions.
    if (isHtmlAriaDisabledTrue(el)) continue;
    if (hasDisabledTextSignal(htmlTextContent(el))) continue;
    emit(buildViolation(tag, el.loc.start, hit, getHtmlAttribute(el, "role")));
  }
}

/**
 * True if the element's immediate parent contains a sibling `<a>`, OR
 * if the grandparent contains a sibling wrapper (e.g. `<li>`) that
 * contains an `<a>` — the canonical pagination shape wraps each page
 * in a `<li>`, so the anchor isn't a DOM-sibling of the surrogate
 * span but shares a grand-parent.
 */
function htmlNearSiblingAnchor(
  self: HtmlElement,
  parentOf: ReadonlyMap<HtmlElement, HtmlElement>,
): boolean {
  const parent = parentOf.get(self);
  if (!parent) return false;
  if (htmlParentHasSiblingAnchor(parent, self)) return true;
  const grandparent = parentOf.get(parent);
  if (!grandparent) return false;
  return htmlParentHasSiblingAnchor(grandparent, parent);
}

function buildHtmlParentMap(doc: HtmlDocument): Map<HtmlElement, HtmlElement> {
  const parentOf = new Map<HtmlElement, HtmlElement>();
  const visit = (node: HtmlNode, parent: HtmlElement | null): void => {
    if (node.kind !== "HtmlElement") return;
    if (parent) parentOf.set(node, parent);
    for (const child of node.children) visit(child, node);
  };
  for (const top of doc.children) visit(top, null);
  return parentOf;
}

function htmlParentHasSiblingAnchor(parent: HtmlElement, self: HtmlElement): boolean {
  for (const child of parent.children) {
    if (child.kind !== "HtmlElement") continue;
    if (child === self) continue;
    if (child.tagName.toLowerCase() === "a") return true;
    // Pagination markup often wraps each page in a wrapper (`<li>`,
    // `<div class="page-item">`) containing a single `<a>`. Descend
    // one level into element-children and peek at their tagName so we
    // catch the wrapped-anchor shape.
    if (elementContainsAnchor(child)) return true;
  }
  return false;
}

function elementContainsAnchor(el: HtmlElement): boolean {
  for (const child of el.children) {
    if (child.kind !== "HtmlElement") continue;
    if (child.tagName.toLowerCase() === "a") return true;
  }
  return false;
}

function isHtmlAriaDisabledTrue(el: HtmlElement): boolean {
  const value = getHtmlAttribute(el, "aria-disabled");
  if (value === null) return false;
  return value.trim().toLowerCase() === "true";
}

// ---------------------------------------------------------------------------
// JSX
// ---------------------------------------------------------------------------

function checkJsx(module: TsxModule, emit: Emit): void {
  const parentOf = buildJsxParentMap(module);
  for (const el of walkJsxElements(module)) {
    const candidate = prepareJsxCandidate(el, parentOf);
    if (candidate === null) continue;
    emit(
      buildViolation(
        el.tagName.toLowerCase(),
        el.loc.start,
        candidate.hit,
        getJsxAttributeString(el, "role"),
      ),
    );
  }
}

/**
 * Runs the JSX-side gate: non-interactive tag, disabled-signalling
 * class, sibling-anchor in parent/grandparent, no `aria-disabled`, no
 * disabled-state word in visible text. Returns the fields needed to
 * build a violation, or null if the element is not a surrogate.
 */
function prepareJsxCandidate(
  el: JsxElement,
  parentOf: ReadonlyMap<JsxElement, JsxElement>,
): { readonly hit: SurrogateHit } | null {
  const tag = el.tagName.toLowerCase();
  if (!SURROGATE_TAGS.has(tag)) return null;
  if (isJsxPascalCase(el.tagName)) return null;
  const classValue = getJsxAttributeString(el, "className") ?? getJsxAttributeString(el, "class");
  if (classValue === null) return null;
  const hit = firstSurrogateHit(classValue);
  if (hit === null) return null;
  if (!jsxNearSiblingAnchor(el, parentOf)) return null;
  if (isJsxAriaDisabledTrue(el)) return null;
  if (hasDisabledTextSignal(jsxTextContent(el))) return null;
  return { hit };
}

function jsxNearSiblingAnchor(
  self: JsxElement,
  parentOf: ReadonlyMap<JsxElement, JsxElement>,
): boolean {
  const parent = parentOf.get(self);
  if (!parent) return false;
  if (jsxParentHasSiblingAnchor(parent, self)) return true;
  const grandparent = parentOf.get(parent);
  if (!grandparent) return false;
  return jsxParentHasSiblingAnchor(grandparent, parent);
}

function buildJsxParentMap(module: TsxModule): Map<JsxElement, JsxElement> {
  const parentOf = new Map<JsxElement, JsxElement>();
  const visit = (node: JsxNode, parent: JsxElement | null): void => {
    if (node.kind !== "JsxElement") return;
    if (parent) parentOf.set(node, parent);
    for (const child of node.children) visit(child, node);
  };
  for (const top of module.jsxElements) visit(top, null);
  return parentOf;
}

function jsxParentHasSiblingAnchor(parent: JsxElement, self: JsxElement): boolean {
  for (const child of parent.children) {
    if (child.kind !== "JsxElement") continue;
    if (child === self) continue;
    if (child.tagName.toLowerCase() === "a") return true;
    if (jsxElementContainsAnchor(child)) return true;
  }
  return false;
}

function jsxElementContainsAnchor(el: JsxElement): boolean {
  for (const child of el.children) {
    if (child.kind !== "JsxElement") continue;
    if (child.tagName.toLowerCase() === "a") return true;
  }
  return false;
}

function isJsxAriaDisabledTrue(el: JsxElement): boolean {
  const value = getJsxAttributeString(el, "aria-disabled");
  if (value === null) return false;
  return value.trim().toLowerCase() === "true";
}

function isJsxPascalCase(tagName: string): boolean {
  const first = tagName[0];
  return first !== undefined && first >= "A" && first <= "Z";
}

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

/**
 * Returns the first surrogate-indicator token in the class list, or
 * `null` if none. Preserves the author's original casing on the
 * returned token so the violation can echo what they wrote.
 */
function firstSurrogateHit(classValue: string): SurrogateHit | null {
  const tokens = classValue.split(/\s+/u).filter((t) => t.length > 0);
  for (const tok of tokens) {
    const lower = tok.toLowerCase();
    if (STRONG_DISABLED_TOKENS.has(lower)) return { kind: "strong", token: tok };
  }
  for (const tok of tokens) {
    const lower = tok.toLowerCase();
    if (DIRECTIONAL_TOKENS.has(lower)) return { kind: "directional", token: tok };
  }
  return null;
}

function hasDisabledTextSignal(text: string): boolean {
  const lower = text.toLowerCase();
  for (const word of DISABLED_TEXT_WORDS) {
    if (lower.includes(word)) return true;
  }
  return false;
}

function buildViolation(
  tag: string,
  loc: { readonly line: number; readonly column: number },
  hit: SurrogateHit,
  role: string | null,
): Parameters<Emit>[0] {
  const roleSuggestion =
    hit.kind === "directional" ? 'role="link" aria-disabled="true"' : 'aria-disabled="true"';
  const currentRolePhrase = role === null ? "no role" : `role="${role}"`;
  const triggerPhrase =
    hit.kind === "strong"
      ? `class token "${hit.token}" signals a disabled control`
      : `class token "${hit.token}" (a pagination directional) next to sibling <a> links makes this a disabled-link surrogate`;
  const message = `<${tag}> with ${triggerPhrase}, but ${currentRolePhrase} and no aria-disabled — screen readers will announce it as static text and the disabled-control state is lost.`;
  const suggestion = buildSuggestion(tag, hit, roleSuggestion);
  return {
    severity: "warning",
    location: { filePath: "", line: loc.line, column: loc.column },
    message,
    suggestion,
  };
}

function buildSuggestion(tag: string, hit: SurrogateHit, roleSuggestion: string): string {
  if (hit.kind === "directional") {
    return `Add ${roleSuggestion} to this <${tag}> so screen readers announce "link, dimmed" instead of plain text (example: <${tag} class="${hit.token}" role="link" aria-disabled="true">). Alternatively, include a disabled-state word in the visible text ("Previous (unavailable)") so the accessible name carries the signal. If this is genuinely a non-control (decorative separator, label), rename the class to something that doesn't imply a disabled control.`;
  }
  return `Add aria-disabled="true" to this <${tag}> so the disabled state reaches the accessibility tree (example: <${tag} class="${hit.token}" aria-disabled="true">). If the element is standing in for a link (e.g. a pagination control with no target), also add role="link". Alternatively, include a disabled-state word in the visible text ("Unavailable") so the accessible name carries the signal.`;
}
